#!/bin/bash
# Fondos IA de la grilla NOVIEMBRE 2026 · Rentas — Seedream 5 Pro con foto REAL de Valle
# Altiplánico como referencia (A-03: no tocar arquitectura ni encuadre, sólo luz y personas).
cd "$(dirname "$0")/../../../.."
PY=~/copylab-venv/Scripts/python.exe
F=out/rentas/20261100_grilla_noviembre/fondos
REAL="Photorealistic documentary photo, natural Chilean people with natural skin, candid, not posed, no text, no logos, no brands, no watermark."
Q="Keep the real architecture of the reference EXACTLY: the white pergola, the brick walls with built-in grills, the artificial grass, the lamp posts and the surrounding buildings. Do not invent landscape."
gen(){ $PY scripts/magnific.py seedream "$2" --aspecto "$3" --refs $4 --out "$F/ia/$1.png" > "$F/ia/$1.log" 2>&1; echo "[$1] $(tail -1 $F/ia/$1.log)"; }

# ── CARRUSEL VIVE AL AIRE LIBRE 24-11 (el texto de la portada va ABAJO, el de los tips ARRIBA)
gen al_1 "This is the real barbecue area (quincho) of a condominium in Calama, Chile. $Q Change the light to warm late-afternoon golden hour, low sun, long soft shadows, warm clear desert sky. Add three friends in their 30s arriving at the quincho, smiling, one woman in front carrying a woven basket, casual summer clothes. People at realistic scale in the MIDDLE band of the frame. The bottom 30% of the frame is just grass, keep it clean. $REAL" carrusel "$F/refs/quincho.jpg" &
gen al_2 "This is the real barbecue area (quincho) of a condominium in Calama, Chile. $Q Warm late-afternoon light. A man in his 30s arrives carrying a blue portable cooler and chats, smiling, with a neighbor woman standing next to the grill, as if agreeing on the booking of the space. Both people in the LOWER HALF of the frame, medium shot; the upper 40% of the frame is calm (pergola and sky). $REAL" carrusel "$F/refs/quincho.jpg" &
gen al_3 "This is the real barbecue area (quincho) of a condominium in Calama, Chile. $Q Warm late-afternoon light. Under the pergola there is a simple wooden outdoor sofa; a woman in her 30s is arranging colorful cushions and a light linen throw blanket on it, cozy corner. Closer medium shot, the woman and sofa in the LOWER HALF of the frame; upper 40% calm (pergola slats and sky). $REAL" carrusel "$F/refs/quincho.jpg" &
gen al_4 "This is the real barbecue area (quincho) of a condominium in Calama, Chile. $Q Sunset, warm golden light, string lights on the pergola just turned on. A group of six friends and family of different ages gathered around a wooden table under the pergola, laughing, sharing food and drinks, a child among them. Group in the LOWER HALF of the frame; upper 40% calm (pergola and warm sky). $REAL" carrusel "$F/refs/quincho.jpg" &
gen al_5 "This is the real green area of a condominium in Calama, Chile, with the buildings and playground. Keep the real buildings, trees, playground and paths EXACTLY; do not invent landscape. Change the light to warm golden hour. Add one person seen from behind, standing on the path in the middle of the frame, arms open wide, as if showing the space. Person small-medium, centered vertically in the frame; the bottom 35% of the frame is calm ground. $REAL" carrusel "$F/refs/areas.jpg" &

# ── CARRUSEL PAID 17-11 (texto ARRIBA: la gente va en la mitad baja)
gen pd_2 "This is the real kitchen of an apartment in the Valle Altiplanico condominium. Keep the kitchen EXACTLY as it is (granite counter, cabinets, built-in microwave, oven). Widen the view to show the kitchen from the living area. A woman in her 30s visiting the apartment opens a cabinet and looks around with curiosity, a friendly real-estate agent in a light blue shirt stands a step behind her, holding a folder. People in the LOWER 60% of the frame, the upper part shows the kitchen wall and ceiling. Soft natural daylight. $REAL" carrusel "$F/refs/cocina.jpg" &
gen pd_3 "This is the real kitchen of an apartment in the Valle Altiplanico condominium. Keep the granite counter and cabinets EXACTLY. Close-medium shot: a young couple leaning on the kitchen counter calmly reading a short printed rental contract together, relaxed and smiling, a cup of coffee on the counter. The paper has no legible text. People and paper in the LOWER 60% of the frame; the upper part is the calm cabinet wall. Soft natural daylight. $REAL" carrusel "$F/refs/cocina.jpg" &
gen pd_4 "This is the real living room of an apartment in the Valle Altiplanico condominium. Keep the room, walls, sofa and window EXACTLY. A woman in her 30s sits on the sofa smiling while chatting on her smartphone (screen facing away, not readable), relaxed, as if talking with her executive by WhatsApp. Medium shot, the woman in the LOWER 60% of the frame; the upper part is the calm wall. Soft natural daylight. $REAL" carrusel "$F/refs/living.jpg" &

# ── Relight de cambio mínimo (estático 10-11 y ST encuesta 25-11)
gen es_quincho "Keep this real photo almost unchanged: same framing, same architecture, same objects. Only change the light to a warm late afternoon: warm golden sunlight on the pergola and the grass, long soft shadows, sky slightly warmer and softer. Do not add or remove anything. No people. Photorealistic." carrusel "$F/refs/quincho.jpg" &
gen st_areas "Keep this real photo almost unchanged: same buildings, trees, playground and paths. Only change the light to sunset golden hour: warm low sun, long shadows, warm pink-orange sky. Do not add or remove anything. No people. Photorealistic." story "$F/refs/areas.jpg" &
wait
